            mean_results = {}
            backend_tried = None

    # Attempt numpy if needed
    if not mean_results and prefer_backend in ('numpy', 'auto'):
        try:
            np_spec = importlib.util.find_spec('numpy')
            if np_spec is not None:
                import numpy as np
                backend_tried = 'numpy'
                for k, lst in data.items():
                    mean_results[k] = float(np.mean(np.asarray(lst)))
        except Exception:
            mean_results = {}
            backend_tried = None

