    # Calculate the inverse document frequency (IDF) for each word
    idf_scores = {}
    for tf_score in tf_scores:
        for word in tf_score:
            if word not in idf_scores:
                idf_scores[word] = 1
            else:
                idf_scores[word] += 1
    for word in idf_scores:
        idf_scores[word] = len(documents) / idf_scores[word]

