def task_func(points):
    """
    Calculate Euclidean distances between consecutive 2D points.

    Each element in `points` may be:
      - a number (int/float) -> treated as (n, n)
      - a sequence of 1 number -> treated as (n, n)
      - a sequence of >=2 numbers -> first two values used as (x, y)

    Returns a list of distances between consecutive points. If `points` has
    length 0 or 1, returns an empty list.

    Example:
    >>> task_func([(1, 2), (4), (-1.2, 4)])
    [3.605551275463989, 5.2]
    """
    import math

    if not points or len(points) < 2:
        return []

    def to_xy(p):
        # numeric (int/float) -> (p, p)
        if isinstance(p, (int, float)):
            return float(p), float(p)
        # reject strings explicitly
        if isinstance(p, str):
            raise TypeError(f"Point {p!r} is not a valid numeric point")
        # try to treat as sequence
        try:
            seq = list(p)
        except TypeError:
            raise TypeError(f"Point {p!r} is not a number or sequence")
        if len(seq) == 0:
            raise ValueError("Point sequences must have at least one value")
        if len(seq) == 1:
            x = seq[0]
            if not isinstance(x, (int, float)):
                raise TypeError(f"Point coordinate {x!r} is not numeric")
            return float(x), float(x)
        x, y = seq[0], seq[1]
        if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
            raise TypeError(f"Point coordinates {x!r}, {y!r} must be numeric")
        return float(x), float(y)

    coords = [to_xy(p) for p in points]
    distances = []
    for (x1, y1), (x2, y2) in zip(coords, coords[1:]):
        distances.append(math.hypot(x2 - x1, y2 - y1))
    return distances

