import unicodedata
from typing import Tuple, Optional
from PIL import Image
import pytesseract
import chardet

def extract_text_from_image_with_comment_fallback(image_path: str, ocr_lang: str = 'eng') -> Tuple[str, str]:
    """
    Open an image, attempt OCR to extract text, normalize/convert to UTF-8,
    and if OCR yields no meaningful text, fall back to image comment/EXIF user comment.

    Returns (text, source) where source is 'ocr', 'image_comment', or 'none'.

    Dependencies:
      - Pillow (PIL)
      - pytesseract (requires Tesseract installed)
      - chardet

    Example:
      text, source = extract_text_from_image_with_comment_fallback('photo.jpg')
    """
    def ensure_utf8_and_normalize(s: str) -> str:
        # Normalize and ensure valid UTF-8 string (replace undecodable parts if any)
        if isinstance(s, bytes):
            # Detect likely encoding and decode
            det = chardet.detect(s)
            enc = det.get('encoding') or 'utf-8'
            try:
                decoded = s.decode(enc, errors='replace')
            except Exception:
                decoded = s.decode('utf-8', errors='replace')
            s = decoded
        # If it's already a str, normalize unicode form
        s = unicodedata.normalize("NFC", s)
        # Optionally strip leading/trailing whitespace
        return s

    def extract_image_comment(img: Image.Image) -> Optional[str]:
        # Try common places where comments may be stored
        # 1) PNG tEXt / info dictionary keys
        info = img.info or {}
        # Common keys that may contain textual metadata
        candidate_keys = ['comment', 'Comment', 'description', 'Description', 'Text', 'text']
        for k in candidate_keys:
            if k in info:
                val = info[k]
                if isinstance(val, bytes):
                    det = chardet.detect(val)
                    enc = det.get('encoding') or 'utf-8'
                    try:
                        return val.decode(enc, errors='replace')
                    except Exception:
                        return val.decode('utf-8', errors='replace')
                elif isinstance(val, str):
                    return val

        # 2) JPEG comment (Pillow sometimes exposes it as 'comment' or under .info)
        if 'comment' in info:
            c = info['comment']
            if isinstance(c, bytes):
                det = chardet.detect(c)
                enc = det.get('encoding') or 'utf-8'
                try:
                    return c.decode(enc, errors='replace')
                except Exception:
                    return c.decode('utf-8', errors='replace')
            elif isinstance(c, str):
                return c

        # 3) EXIF user comment (tag 37510)
        try:
            exif = img.getexif()
            if exif:
                user_comment = exif.get(37510)  # UserComment
                if user_comment:
                    # EXIF user comment can be bytes (and may include encoding prefix)
                    if isinstance(user_comment, bytes):
                        # Some EXIF user comments start with an ASCII encoding prefix like b'ASCII\x00\x00\x00'
                        # Try to strip common prefixes
                        prefixes = [b'ASCII\x00\x00\x00', b'UNICODE\x00', b'JIS\x00\x00\x00']
                        for p in prefixes:
                            if user_comment.startswith(p):
                                candidate = user_comment[len(p):]
                                det = chardet.detect(candidate)
                                enc = det.get('encoding') or 'utf-8'
                                try:
                                    return candidate.decode(enc, errors='replace')
                                except Exception:
                                    return candidate.decode('utf-8', errors='replace')
                        # If no known prefix found, try detect & decode whole blob
                        det = chardet.detect(user_comment)
                        enc = det.get('encoding') or 'utf-8'
                        try:
                            return user_comment.decode(enc, errors='replace')
                        except Exception:
                            return user_comment.decode('utf-8', errors='replace')
                    elif isinstance(user_comment, str):
                        return user_comment
        except Exception:
            # Some images may not support getexif(); ignore quietly
            pass

        return None

    # 1) Open image
    img = Image.open(image_path)

    # 2) Try OCR
    try:
        ocr_raw = pytesseract.image_to_string(img, lang=ocr_lang)
    except Exception as e:
        # If pytesseract fails (e.g., lang not installed), treat as empty and continue to fallback
        ocr_raw = ''

    ocr_text = ensure_utf8_and_normalize(ocr_raw) if ocr_raw else ''
    if ocr_text and ocr_text.strip():
        return ocr_text, 'ocr'

    # 3) Fallback: try image comment / EXIF
    comment = extract_image_comment(img)
    if comment:
        comment_norm = ensure_utf8_and_normalize(comment)
        if comment_norm.strip():
            return comment_norm, 'image_comment'

    # 4) Nothing found
    return '', 'none'
